catalog_script_client.script:
/**
 * Function to extract the parameter value from the url
 */

function getParmVal(name){
    name = name.replace(/[\[]/, "\\\[").replace(/[\]]/, "\\\]");  
    var regexS = "[\\?&]" + name + "=([^&#]*)";  
    var regex = new RegExp(regexS);  
    var results = regex.exec(top.location);  
    if (results == null) {  
        return "";  
    } else {  
        return unescape(results[1]);  
    }  
}

/**
 * Function to set values in the form field
 * 
 */
function setParmVal(field_id, value) {
    g_form.setValue(field_id, value);	
}


/**
 * On Click Submit, below function will change the status of task to complete and
 * update the parent case with the information added by the manager
 * 
 */

function onSubmit() {
   //Type appropriate comment here, and begin script below
   var parent_case_number = getParmVal('parent_case_number');

   var ga = new GlideAjax("x_hccc_hoc_ohs.HoCDisabilityAccommodation");
   ga.addParam('sysparm_name', 'updateParentOHSMCase');
   ga.addParam('sysparm_case_id', parent_case_number);
   ga.addParam("sysparm_last_name", g_form.getValue("last_name"));
   ga.addParam("sysparm_first_name", g_form.getValue("first_name"));
   ga.addParam("sysparm_position_title", g_form.getValue("position_title"));
   ga.addParam("sysparm_decision", g_form.getValue("decision"));
   ga.addParam("sysparm_accommodation_is_denied", g_form.getValue("accommodation_is_denied"));
   ga.addParam("sysparm_other_reasons", g_form.getValue("other_reasons"));
   ga.addParam("sysparm_employee_be_accommodated", g_form.getValue("how_will_the_employee_be_accommodated"));

ga.getXMLAnswer(function(response) {
	var data = JSON.parse(response);
	if (data.error) {
            alert(data.error);
        } else {
			// var redirectURL = "https://hoccdcdv.service-now.com/services?id=hoc_my_dashboard";
			// window.location.href = redirectURL;
            //g_form.addInfoMessage("Thank you for submitting the information");
			top.window.location = "services?id=hrm_todos_page";
        }
	});

}
